local function sQ(a,b) return {qmul(a[1],a[2],a[3],a[4],b[1],b[2],b[3],b[4])} end
local function sInv(a) return {-a[1],-a[2],-a[3],a[4]} end
local function sV(q,v) return {qrot(q[1],q[2],q[3],q[4],v[1],v[2],v[3])} end
local function sAdd(a,b) return {a[1]+b[1],a[2]+b[2],a[3]+b[3]} end
local function sSub(a,b) return {a[1]-b[1],a[2]-b[2],a[3]-b[3]} end
local function sMul(a,k) return {a[1]*k,a[2]*k,a[3]*k} end
local function sDot(a,b) return a[1]*b[1]+a[2]*b[2]+a[3]*b[3] end
local function sNorm(a) local n=math.sqrt(sDot(a,a));if n<1e-12 then return nil end;return sMul(a,1/n) end
local function sCross(a,b) return {a[2]*b[3]-a[3]*b[2],a[3]*b[1]-a[1]*b[3],a[1]*b[2]-a[2]*b[1]} end
local function sNormalizeQ(q) local n=math.sqrt(q[1]^2+q[2]^2+q[3]^2+q[4]^2);return {q[1]/n,q[2]/n,q[3]/n,q[4]/n} end
local function sClose(a,b,eps)
 if type(a)~=type(b) then return false end
 if type(b)=='table' then for k,v in pairs(b) do if not sClose(a[k],v,eps) then return false end end;return true end
 if type(b)=='number' then return a==a and math.abs(a-b)<(eps or 1e-6) end
 return a==b
end
local function sRead(S,u,n)
 local x,y,z=read_vec3(S,S.Unit.world_position(u,n));local a,b,c,d=read_quat4(S,u,n)
 if x==nil or a==nil then return nil end
 return {p={x,y,z},q={a,b,c,d}}
end
local function sRawInterp(control,rules)
 control=sNormalizeQ(control)
 local weights,total={},0
 for i,r in ipairs(rules) do
  local dot=math.min(1,math.abs(control[1]*r.trigger[1]+control[2]*r.trigger[2]+control[3]*r.trigger[3]+control[4]*r.trigger[4]))
  local w=math.max(0,1-2*math.acos(dot)*r.invTolerance);weights[i]=w;total=total+w
 end
 if total<=.001 then return sNormalizeQ(rules[1].rotation),{unpack(rules[1].position)},true end
 local q,p={0,0,0,0},{0,0,0}
 for i,r in ipairs(rules) do if weights[i]>0 then
  local w=weights[i]/total
  local dot=q[1]*r.rotation[1]+q[2]*r.rotation[2]+q[3]*r.rotation[3]+q[4]*r.rotation[4]
  if dot<0 then for k=1,4 do q[k]=-q[k] end end
  for k=1,4 do q[k]=q[k]+w*r.rotation[k] end
  for k=1,3 do p[k]=p[k]+w*r.position[k] end
