end
M.test1201_raw_interp=sRawInterp
-- C++ operation order: gravity/lateral forces, Euler, signed planes, cone,
-- rod length, tangent velocity, roll, then independent base spring/next-step friction.
local function sJiggle(state,goal,rec,dt,now,alignQ)
 local p,flags=rec.params,rec.flags;local scale=T1201.unitScale
 local left,up,forward=sV(goal.q,{1,0,0}),sV(goal.q,{0,1,0}),sV(goal.q,{0,0,1})
 local length=p.length*scale;local goalTip=sAdd(goal.p,sMul(forward,length));local gravity=sV(alignQ or T1201.alignQ,{0,0,-1})
 if state.tip==nil or now-(state.lastUpdate or now)>.5 then
  state.tip={unpack(goalTip)};state.vel={0,0,0};state.base={unpack(goal.p)};state.baseVel={0,0,0};state.baseLast={unpack(goal.p)};state.baseAccel={0,0,0};state.lastUpdate=now;state.jiggleCount=16;state.goalCount=0
 end
 local h=now-state.lastUpdate;local useGoal=h>1/20
 if useGoal then state.goalCount=32 elseif state.goalCount>0 then useGoal=true;state.goalCount=state.goalCount-1 else state.jiggleCount=32 end
 if state.jiggleCount>0 then state.jiggleCount=state.jiggleCount-1;state.goalCount=0;useGoal=false end
 if h<.001 then h=.001 elseif useGoal then state.cutoff=(state.cutoff or 0)+1;return {p={unpack(goal.p)},q={unpack(goal.q)}} end
 state.lastUpdate=now
 local result={p={unpack(goal.p)},q={unpack(goal.q)}}
 if flag_set(flags,1) or flag_set(flags,2) then
  local accel=sMul(gravity,p.tipMass*scale)
  if flag_set(flags,1) then
   local err=sSub(goalTip,state.tip)
   accel=sAdd(accel,sMul(left,p.yawStiffness*sDot(left,err)-p.yawDamping*sDot(left,state.vel)))
   accel=sAdd(accel,sMul(up,p.pitchStiffness*sDot(up,err)-p.pitchDamping*sDot(up,state.vel)))
   if not flag_set(flags,32) then accel=sAdd(accel,sMul(forward,p.alongStiffness*sDot(forward,err)-p.alongDamping*sDot(forward,state.vel))) end
  end
  state.vel=sAdd(state.vel,sMul(accel,h));state.tip=sAdd(state.tip,sMul(state.vel,h))
  local along=sSub(state.tip,goal.p);local x,y,z=sDot(left,along),sDot(up,along),sDot(forward,along)
  if flag_set(flags,4) then
   local angle=math.atan2(x,z);local limit=nil
   if angle<p.minYaw then limit=p.minYaw elseif angle>p.maxYaw then limit=p.maxYaw end
   if limit~=nil then local sn,cs=math.sin(limit),math.cos(limit);local a=x*sn+z*cs;x,z=a*sn,a*cs;state.tip=sAdd(goal.p,sAdd(sMul(up,y),sAdd(sMul(left,x),sMul(forward,z))));state.vel={0,0,0};state.contacts=(state.contacts or 0)+1 end
  end
  if flag_set(flags,8) then
   local angle=math.atan2(y,z);local limit=nil
   if angle<p.minPitch then limit=p.minPitch elseif angle>p.maxPitch then limit=p.maxPitch end
   if limit~=nil then local sn,cs=math.sin(limit),math.cos(limit);local a=y*sn+z*cs;y,z=a*sn,a*cs;state.tip=sAdd(goal.p,sAdd(sMul(left,x),sAdd(sMul(up,y),sMul(forward,z))));state.vel={0,0,0};state.contacts=(state.contacts or 0)+1 end
  end
  local f=sNorm(sSub(state.tip,goal.p)) or forward
  if flag_set(flags,16) then
   local dot=math.max(-1,math.min(1,sDot(f,forward)));local angle=math.acos(dot);if dot<0 then angle=2*math.pi-angle end
   if angle>p.angleLimit then
    local d=sNorm(sSub(goalTip,state.tip)) or forward
    state.tip=sSub(goalTip,sMul(d,length*math.sin(p.angleLimit)));f=sNorm(sSub(state.tip,goal.p)) or forward
   end
  end
  if flag_set(flags,32) then state.tip=sAdd(goal.p,sMul(f,length));state.vel=sSub(state.vel,sMul(f,sDot(state.vel,f))) end
  local l=sNorm(sCross(up,f))
  if l==nil then state.degenerate=(state.degenerate or 0)+1;l=left;f=forward end
  local u=sCross(f,l)
  result.q={stored9_quaternion({l[1],l[2],l[3],u[1],u[2],u[3],f[1],f[2],f[3]})}
 end
 if flag_set(flags,64) then
  local accel=sAdd(state.baseAccel,sAdd(sMul(gravity,p.baseMass*scale),sSub(sMul(sSub(goal.p,state.base),p.baseStiffness),sMul(state.baseVel,p.baseDamping))))
  state.baseVel=sAdd(state.baseVel,sMul(accel,h));state.base=sAdd(state.base,sMul(state.baseVel,h));state.baseAccel={0,0,0}
  local err=sSub(state.base,goal.p);local axes={left,up,forward};local lo={p.baseMinLeft,p.baseMinUp,p.baseMinForward};local hi={p.baseMaxLeft,p.baseMaxUp,p.baseMaxForward};local friction={p.baseLeftFriction,p.baseUpFriction,p.baseForwardFriction};local components={sDot(left,err),sDot(up,err),sDot(forward,err)}
  for k=1,3 do
   local value=components[k];components[k]=math.max(lo[k]*scale,math.min(hi[k]*scale,value))
   if components[k]~=value then local tangent=sSub(state.baseVel,sMul(axes[k],sDot(axes[k],state.baseVel)));state.baseAccel=sSub(state.baseAccel,sMul(tangent,friction[k])) end
  end
  state.base=sAdd(goal.p,sAdd(sMul(left,components[1]),sAdd(sMul(up,components[2]),sMul(forward,components[3]))))
  state.baseVel=sMul(sSub(state.base,state.baseLast),1/h);state.baseLast={unpack(state.base)};result.p={unpack(state.base)}
 end
 return result
end
M.test1201_jiggle=sJiggle
local function sRig(r) return r~=nil and r.version==2 and r.drivers~=nil and r.drivers.version==3 and #r.bones==49 and #r.drivers.bones==11 and sClose(r,T1201.rig) end
M.test1201_matches_rig=sRig

-- Unit.name_hash is the scene instance/name identity, NOT the resource identity.
-- Use the same real-engine contract as the production attachment/FP modules.
local function sResourceId(S,unit)
 if type(S.Unit.resource_name)~='function' or type(S.IdString64)~='table' or type(S.IdString64.to_hex)~='function' then return nil,'missing-resource-api' end
 local ok,raw=pcall(S.Unit.resource_name,unit);if not ok or raw==nil then return nil,'resource-name-failed' end
 local converted,hex=pcall(S.IdString64.to_hex,raw)
 if not converted or type(hex)~='string' then return nil,'resource-to-hex-failed' end
 hex=hex:lower():gsub('^0x','')
 if #hex~=16 or not hex:match('^%x+$') then return nil,'invalid-resource-hex' end
 return hex,'Unit.resource_name',type(raw)
end
M.test1201_resource_id=sResourceId
local old1201Attach,old1201Update,old1201Release=M.attach,M.update,M.release
function M.attach(S,unit,rig,options)
 -- With production gating, this exact scoped rig must pass its full unit/bind
 -- preflight before owning VRD. A rejected original-format instance must not
 -- fall back to legacy driver rows or resurrect a cached driver record.
 if options~=nil and options.vrdSkeletonOnly==true and sRig(rig) then
  local deferred={};for k,v in pairs(options) do deferred[k]=v end
  deferred.deferVrdToScopedSolver=true;options=deferred
 end
 local session=old1201Attach(S,unit,rig,options)
 if not sRig(rig) or session==nil or session.dead~=nil then return session end
 local log=session.logger or function()end
 local rid,identityApi,rawType=sResourceId(S,unit)
 local profile=rid and T1201.units[rid] or nil
 if profile==nil or session.nodeCount~=T1201.nodeCount then
  log('[test1201-source] rejected resource/count api=%s rawType=%s rid=%s actualNodes=%s expectedNodes=%d',tostring(identityApi),tostring(rawType),tostring(rid),tostring(session.nodeCount),T1201.nodeCount)
  return session
 end
 local st={time=0,frames=0,records={},saved={},last={},profile=profile,resource=rid};local seen={}
 local okPrepare,reason=pcall(function()
  assert(type(S.Quaternion.from_elements)=="function" and type(S.Matrix4x4.from_quaternion_position)=="function" and type(S.Unit.set_local_pose)=="function","missing-source-writer-api")
  -- All 60 physical nodes, canonical nodes and initial writable/pre-bind frames
  -- are validated before the scoped path can write anything.
  for _,rec in ipairs(profile.canonical) do
   assert(M.resolve_named_node(S,unit,rec.targetName,T1201.nodeCount)==rec.node,'canonical-node')
  end
  for _,rec in ipairs(profile.records) do if not rec.excludedWrist then
   assert(not seen[rec.node] and rec.node>=1 and rec.node<=T1201.nodeCount,'duplicate/index');seen[rec.node]=true
   assert(M.resolve_named_node(S,unit,rec.name,T1201.nodeCount)==rec.node,'physical-node')
   local before=snapshot_pose(S,S.Unit.local_pose(unit,rec.node));assert(before~=nil,'local-pose');local localQ={stored9_quaternion(before.r)};local localP={before.px,before.py,before.pz}
   local parent,own=sRead(S,unit,rec.parentNode),sRead(S,unit,rec.node);assert(parent~=nil and own~=nil,'world-read')
   local relQ=sQ(sInv(parent.q),own.q);local preQ=sQ(relQ,sInv(localQ));local relP=sV(sInv(parent.q),sSub(own.p,parent.p));local preP=sSub(relP,sV(preQ,localP))
   -- Source extras use a shipped bind contract. Accept full-local or the measured
   -- engine pre-bind contract, never a first-frame guess at Source's rest axes.
   local d1=math.abs(preQ[4]);local d2=math.abs(preQ[1]*rec.targetLocalQ[1]+preQ[2]*rec.targetLocalQ[2]+preQ[3]*rec.targetLocalQ[3]+preQ[4]*rec.targetLocalQ[4])
   assert(d1>0.999999 or d2>0.999999,string.format('unknown-pre-bind bone=%s node=%d identityDot=%.9f bindDot=%.9f localQ=(%.6f,%.6f,%.6f,%.6f)',rec.name,rec.node,d1,d2,localQ[1],localQ[2],localQ[3],localQ[4]))
   local expectedQ=sQ(preQ,localQ);assert(math.abs(expectedQ[1]*rec.targetLocalQ[1]+expectedQ[2]*rec.targetLocalQ[2]+expectedQ[3]*rec.targetLocalQ[3]+expectedQ[4]*rec.targetLocalQ[4])>.999999,string.format('changed-rest bone=%s node=%d relativeQ=(%.6f,%.6f,%.6f,%.6f)',rec.name,rec.node,expectedQ[1],expectedQ[2],expectedQ[3],expectedQ[4]))
   assert(sDot(sSub(relP,rec.targetLocalP),sSub(relP,rec.targetLocalP))<1e-8,string.format('changed-position bone=%s node=%d errorM=%.9f world=(%.3f,%.3f,%.3f)',rec.name,rec.node,math.sqrt(sDot(sSub(relP,rec.targetLocalP),sSub(relP,rec.targetLocalP))),own.p[1],own.p[2],own.p[3]))
   st.records[rec.source]={preQ=preQ,preP=preP};st.saved[#st.saved+1]={node=rec.node,pose=before}
  end end
 end)
 if not okPrepare then log('[test1201-source] rejected atomic-preflight=%s',tostring(reason));return session end
 session.test1201Source=st;session.excludedWristDrivers=2;session.vrdPolicyBlocked=false;session.vrdContract="test1201-source-full-bind"
 log('[test1201-source] SELECTED profile=%s rid=%s nodes=%d identity=Unit.resource_name spring=49 driver=9 wristExcluded=2 referenceDrivers=11 canonical=%d sourceUnits=.0254 noVRDfilter=true noWorldAnchor=true wind=none gravity=tipMass/baseMass*.0254',T1201.profile,rid,session.nodeCount,#profile.canonical)
 return session
end
function M.update(session,dt,maxWrite)
 if session==nil or session.test1201Source==nil then return old1201Update(session,dt,maxWrite) end
 if M.session_health(session,M.frame)~='ok' then return 0 end
 local S,unit,st=session.S,session.unit,session.test1201Source
 local profile=st.profile
 local validCount=S.Unit.num_scene_graph_items(unit);if validCount~=T1201.nodeCount then session.dead='rebuilt';return 0 end
 if M.frame~=nil and st.frame==M.frame then return 0 end;st.frame=M.frame
 if type(dt)~='number' or dt~=dt or dt<=0 or dt==math.huge then dt=1/60 end
 st.time=st.time+dt;st.frames=st.frames+1
 local virtual,target={},{};local plan={};local calls=2
 -- Only animated/non-physical canonical nodes are read. Never consume the
 -- previous frame's helper/spring output as this frame's animation target.
 for _,rec in ipairs(profile.canonical) do
  local actual=sRead(S,unit,rec.node);calls=calls+4
  if actual==nil then session.dead='source-canonical-read';return 0 end
  target[rec.source]=actual
  virtual[rec.source]={p={unpack(actual.p)},q=sQ(sQ(actual.q,sInv(rec.targetBindQ)),rec.virtualBindQ)}
 end
 for _,rec in ipairs(profile.records) do
  local parent=virtual[rec.parent];local goal={p=sAdd(parent.p,sV(parent.q,rec.offset)),q=sQ(parent.q,rec.localQ)};local result
  if rec.kind==2 then
   local control=sQ(sInv(virtual[rec.controlParent].q),virtual[rec.control].q)
   local q,p,outside=sRawInterp(control,rec.rules);goal.q=sQ(parent.q,q);goal.p=sAdd(goal.p,sV(parent.q,sMul(sSub(p,rec.sourceLocalP),T1201.unitScale)))
   result=goal;if outside then st.outside=(st.outside or 0)+1 end
  else result=sJiggle(st.records[rec.source],goal,rec,dt,st.time,profile.alignQ) end
  virtual[rec.source]=result
  local actual={p=result.p,q=sQ(sQ(result.q,sInv(rec.virtualBindQ)),rec.targetBindQ)};target[rec.source]=actual
  if rec.excludedWrist then
   local pt=target[rec.parent];target[rec.source]={p=sAdd(pt.p,sV(pt.q,rec.targetLocalP)),q=sQ(pt.q,rec.targetLocalQ)}
  else
  local pt=target[rec.parent];local localQ=sQ(sInv(pt.q),actual.q);local localP=sV(sInv(pt.q),sSub(actual.p,pt.p));local pre=st.records[rec.source]
  local outputQ=sQ(sInv(pre.preQ),localQ);local outputP=sV(sInv(pre.preQ),sSub(localP,pre.preP))
  for k=1,4 do if outputQ[k]~=outputQ[k] or math.abs(outputQ[k])>1.001 then session.dead='source-invalid-quaternion';return 0 end end
  for k=1,3 do if outputP[k]~=outputP[k] or math.abs(outputP[k])>100 then session.dead='source-invalid-position';return 0 end end
  plan[#plan+1]={node=rec.node,q=outputQ,p=outputP,source=rec.source,kind=rec.kind}
  end
 end
 local written,driverWritten=0,0
 for _,out in ipairs(plan) do
  local last=st.last[out.node];local same=last~=nil and sClose(out.q,last.q,1e-6) and sClose(out.p,last.p,1e-6)
  if not same then
   local q=S.Quaternion.from_elements(out.q[1],out.q[2],out.q[3],out.q[4]);local pose=S.Matrix4x4.from_quaternion_position(q,S.Vector3(out.p[1],out.p[2],out.p[3]));S.Unit.set_local_pose(unit,out.node,pose)
   st.last[out.node]={q=out.q,p=out.p};written=written+1;calls=calls+3;if out.kind==2 then driverWritten=driverWritten+1 end
  end
 end
 if written>0 and session.world~=nil then S.World.update_unit(session.world,unit);calls=calls+1 end

 if st.resource=='34a40a5ae7a392ba' and st.frames==1 then
  local maxQ,maxP,n=0,0,0
  for _,rec in ipairs(profile.records) do if not rec.excludedWrist then
   local actual=sRead(S,unit,rec.node);calls=calls+4;local expected=target[rec.source]
   if actual~=nil then
    local dot=math.abs(actual.q[1]*expected.q[1]+actual.q[2]*expected.q[2]+actual.q[3]*expected.q[3]+actual.q[4]*expected.q[4]);dot=math.min(1,dot)
    maxQ=math.max(maxQ,2*math.acos(dot)*180/math.pi);maxP=math.max(maxP,math.sqrt(sDot(sSub(actual.p,expected.p),sSub(actual.p,expected.p))));n=n+1
   end
  end end
  local log=session.logger or function()end;log('[test1201-source] READBACK rid=%s nodes=%d maxWorldQErrorDeg=%.6f maxWorldPositionErrorM=%.9f finalFlushCount=1',st.resource,n,maxQ,maxP)
 end
 session.engineCalls=calls;session.skippedSame=58-written;session.driverWrites=(session.driverWrites or 0)+driverWritten;session.tipApplied=(session.tipApplied or 0)+1
 st.virtual,st.target=virtual,target

 -- Bounded actual Hips telemetry. All values are already in the numeric solver
 -- cache; no pose rereads, external force, collision or second engine flush.
 if st.resource=='34a40a5ae7a392ba' then
  local hip=nil
  for _,c in ipairs(profile.canonical) do if c.targetName=='hips' then hip=target[c.source];break end end
  local speed=0
  if hip~=nil then
   if st.lastHipP~=nil then local d=sSub(hip.p,st.lastHipP);speed=math.sqrt(sDot(d,d))/math.max(dt,.001) end
   st.lastHipP={unpack(hip.p)}
  end
  if (st.frontSamples or 0)<24 and (st.frames==1 or st.frames%240==0) then
   local values={}
   for _,r in ipairs(profile.records) do if r.name=='pd.022' or r.name=='pd.024' then
    local parent=virtual[r.parent];local goalQ=sQ(parent.q,r.localQ);local outQ=virtual[r.source].q
    local d=sV(sQ(sInv(goalQ),outQ),{0,0,1});local yaw=math.atan2(d[1],d[3])*180/math.pi;local pitch=math.atan2(d[2],d[3])*180/math.pi
    local helper=nil
    for _,h in ipairs(profile.records) do if h.source==r.parent then helper=h;break end end
    local hdeg,ctl=0,{0,0,0,1}
    if helper~=nil then
     local hlocal=sQ(sInv(virtual[helper.parent].q),parent.q);local delta=sQ(hlocal,sInv(helper.localQ));hdeg=2*math.acos(math.min(1,math.abs(delta[4])))*180/math.pi
     ctl=sQ(sInv(virtual[helper.controlParent].q),virtual[helper.control].q)
    end
    values[#values+1]=string.format('%s ctl=(%.4f,%.4f,%.4f,%.4f) helperDelta=%.3f springYaw=%.3f springPitch=%.3f g=%.3f',r.name,ctl[1],ctl[2],ctl[3],ctl[4],hdeg,yaw,pitch,r.params.tipMass*T1201.unitScale)
   end end
   local log=session.logger or function()end;local hp=hip and hip.p or {0,0,0}
   log('[test1201-front] frame=%d dt=%.6f hip=(%.3f,%.3f,%.3f) speed=%.3f wind=none %s',st.frames,dt,hp[1],hp[2],hp[3],speed,table.concat(values,' | '))
   st.frontSamples=(st.frontSamples or 0)+1
  end
 end
 if st.frames==1 or st.frames%240==0 then
  local log=session.logger or function()end
  log('[test1201-source] frame=%d dt=%.6f writes=%d driverWrites=%d outsideFallback=%d finalFlushOnly=true',st.frames,dt,written,driverWritten,st.outside or 0)
 end
 return written
end
function M.release(session)
 if session==nil or session.test1201Source==nil then return old1201Release(session) end
 local st=session.test1201Source;session.test1201Source=nil
 if not M.unit_alive(session.S,session.unit) then return 0 end
 if session.S.Unit.num_scene_graph_items(session.unit)~=T1201.nodeCount then return 0 end
 local n=0
 for _,row in ipairs(st.saved) do local pose=rebuild_pose(session.S,row.pose);if pose~=nil then session.S.Unit.set_local_pose(session.unit,row.node,pose);n=n+1 end end
 if n>0 and session.world~=nil then session.S.World.update_unit(session.world,session.unit) end
 return n
end


